function createZincGranulesApparatus({
  parent,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  radius = 0.035,
  spread = 0.085,
  count = 9,
  materials = {},
  name = 'zinc-granules',
} = {}) {
  const group = new THREE.Group();
  group.name = name;
  applyTransform(group, position, rotation);
  addToParent(parent, group);

  const zincMaterial = cloneMaterial(
    materials.zinc,
    new THREE.MeshStandardMaterial({
      color: 0xc7d0d6,
      roughness: 0.58,
      metalness: 0.72,
    })
  );
  const darkSideMaterial = cloneMaterial(
    materials.darkSide,
    new THREE.MeshStandardMaterial({
      color: 0x8f9aa1,
      roughness: 0.72,
      metalness: 0.55,
    })
  );

  const granules = [];
  const baseScales = [];
  const baseColors = [];
  for (let index = 0; index < count; index += 1) {
    const angle = (index / Math.max(1, count)) * Math.PI * 2;
    const ring = index === 0 ? 0 : spread * (0.42 + (index % 3) * 0.16);
    const granule = new THREE.Mesh(
      new THREE.SphereGeometry(radius * (0.78 + (index % 4) * 0.08), 12, 8),
      index % 4 === 0 ? darkSideMaterial : zincMaterial
    );
    granule.position.set(
      Math.cos(angle) * ring,
      (index % 3) * radius * 0.34,
      Math.sin(angle) * ring * 0.82
    );
    granule.scale.set(1.15, 0.72 + (index % 2) * 0.18, 0.9);
    granule.castShadow = true;
    granule.receiveShadow = true;
    group.add(granule);
    granules.push(granule);
    baseScales.push(granule.scale.clone());
    baseColors.push(granule.material.color.clone());
  }

  const anchors = {
    interactionZone: makeAnchor(group, 0, radius * 0.45, 0, `${name}:interactionZone`),
    effectOrigin: makeAnchor(group, 0, radius * 0.56, 0, `${name}:effectOrigin`),
    labelAnchor: makeAnchor(group, spread * 1.5, radius * 1.8, 0, `${name}:labelAnchor`),
  };

  const apparatus = composeApparatus({
    group,
    name,
    kind: 'zinc-granules',
    family: 'solid-metal-sample',
    capabilities: ['solid-sample', 'metal-sample', 'reactive-surface', 'effect-origin', 'label-anchor', 'interaction-anchor', 'manual-placement'],
    constraints: {
      bounds: {
        width: spread * 2 + radius * 2,
        length: spread * 2 + radius * 2,
        height: radius * 2.5,
      },
    },
    anchors,
    meshes: { granules },
    controllers: {},
  });

  const { labelPlane } = attachFixedPlaneLabel({
    group,
    labelAnchor: anchors.labelAnchor,
  });

  apparatus.controllers.setCorrosionProgress = (progress = 0) => {
    const value = Math.max(0, Math.min(1, progress));
    for (const [index, granule] of granules.entries()) {
      granule.scale.copy(baseScales[index]).multiplyScalar(1 - value * 0.08);
      if (granule.material?.color) {
        granule.material.color.copy(baseColors[index]).lerp(new THREE.Color(0xa9b2b8), value * 0.18);
      }
    }
  };

  attachLabelController(apparatus, labelPlane, { defaultAccent: '#d8dde6' });
  return apparatus;
}

const ZINC_GRANULES_PRESET_DEFINITION = {
  id: 'zinc-granules',
  factory: createZincGranulesApparatus,
};

function createClassicErlenmeyerApparatus({
  parent,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  bodyRadiusTop = 0.44,
  bodyRadiusBottom = 0.68,
  bodyHeight = 1.82,
  neckRadius = 0.18,
  neckHeight = 0.74,
  fillRatio = 0,
  liquidColor = 0xe8f8ff,
  surfaceColor = 0xf8fdff,
  gasColor = null,
  gasOpacity = 0.14,
  gasHeightRatio = 0.62,
  gasBaseY = 0.4,
  materials = {},
  name = 'classic-erlenmeyer',
} = {}) {
  const group = new THREE.Group();
  group.name = name;
  applyTransform(group, position, rotation);
  addToParent(parent, group);

  const glassMaterial = createClassicGlassMaterial(materials);
  const rimMaterial = createClassicGlassRimMaterial(materials);
  const liquidMaterial = createClassicLiquidMaterial(materials, liquidColor);
  const surfaceMaterial = createClassicLiquidSurfaceMaterial(materials, surfaceColor);

  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(bodyRadiusTop, bodyRadiusBottom, bodyHeight, 40, 1, true),
    glassMaterial,
  );
  body.position.y = bodyHeight * 0.5;
  body.castShadow = true;
  body.receiveShadow = true;
  group.add(body);

  const base = new THREE.Mesh(
    new THREE.CircleGeometry(bodyRadiusBottom * 0.96, 40),
    cloneMaterial(materials.base, glassMaterial),
  );
  base.rotation.x = -Math.PI * 0.5;
  base.position.y = 0.015;
  base.receiveShadow = true;
  group.add(base);

  const neck = new THREE.Mesh(
    new THREE.CylinderGeometry(neckRadius, neckRadius * 1.08, neckHeight, 32, 1, true),
    cloneMaterial(materials.neck, glassMaterial),
  );
  neck.position.y = bodyHeight + neckHeight * 0.5 - 0.06;
  neck.castShadow = true;
  neck.receiveShadow = true;
  group.add(neck);

  const lip = new THREE.Mesh(
    new THREE.TorusGeometry(neckRadius * 1.16, neckRadius * 0.08, 14, 32),
    rimMaterial,
  );
  lip.position.y = bodyHeight + neckHeight - 0.06;
  lip.rotation.x = Math.PI * 0.5;
  lip.castShadow = true;
  lip.receiveShadow = true;
  group.add(lip);

  const innerRadius = bodyRadiusTop * 0.76;
  const liquidHeight = bodyHeight * 0.56;
  const liquid = new THREE.Mesh(
    new THREE.CylinderGeometry(bodyRadiusTop * 0.72, bodyRadiusBottom * 0.66, liquidHeight, 32),
    liquidMaterial,
  );
  liquid.position.y = 0.34 + liquidHeight * 0.5;
  liquid.visible = fillRatio > 0.002;
  group.add(liquid);

  const liquidSurface = new THREE.Mesh(
    new THREE.CircleGeometry(bodyRadiusTop * 0.72, 32),
    surfaceMaterial,
  );
  liquidSurface.rotation.x = -Math.PI * 0.5;
  liquidSurface.position.y = 0.34 + liquidHeight * fillRatio;
  liquidSurface.visible = fillRatio > 0.002;
  group.add(liquidSurface);

  let gasVolume = null;
  if (gasColor !== null && gasColor !== undefined) {
    gasVolume = new THREE.Mesh(
      new THREE.CylinderGeometry(bodyRadiusTop * 0.7, bodyRadiusBottom * 0.56, bodyHeight * gasHeightRatio, 28),
      cloneMaterial(
        materials.gas,
        new THREE.MeshPhysicalMaterial({
          color: gasColor,
          transparent: true,
          opacity: gasOpacity,
          roughness: 0.26,
          metalness: 0,
          transmission: 0.12,
          thickness: 0.1,
          depthWrite: false,
        }),
      ),
    );
    gasVolume.position.y = gasBaseY + (bodyHeight * gasHeightRatio) * 0.5;
    group.add(gasVolume);
  }

  const mouthY = bodyHeight + neckHeight - 0.1;
  const anchors = {
    labelAnchor: makeAnchor(group, 0, bodyHeight * 0.52, bodyRadiusBottom + 0.08, `${name}:labelAnchor`),
    gripAnchor: makeAnchor(group, 0, bodyHeight * 0.7, 0, `${name}:gripAnchor`),
    interactionZone: makeAnchor(group, 0, mouthY - 0.16, 0, `${name}:interactionZone`),
    mouth: makeAnchor(group, 0, mouthY, 0, `${name}:mouth`),
    pourTarget: makeAnchor(group, 0, mouthY - 0.14, 0, `${name}:pourTarget`),
    effectOrigin: makeAnchor(group, 0, bodyHeight * 0.52, 0, `${name}:effectOrigin`),
    gasVolume: makeAnchor(group, 0, gasBaseY + (bodyHeight * gasHeightRatio) * 0.5, 0, `${name}:gasVolume`),
    steamOrigin: makeAnchor(group, 0, mouthY - 0.06, 0, `${name}:steamOrigin`),
    heatZone: makeAnchor(group, 0, 0.24, 0, `${name}:heatZone`),
  };

  const state = {
    fillRatio,
    gasOpacity,
  };

  const apparatus = composeApparatus({
    kind: 'classic-erlenmeyer',
    family: 'classic-showcase-vessel',
    group,
    meshes: { body, base, neck, lip, liquid, liquidSurface, gasVolume },
    anchors,
    constraints: {
      innerRadius,
      innerHeight: liquidHeight,
      safeFillHeight: liquidHeight * 0.92,
      safePourRadius: neckRadius * 1.22,
      safePourClearance: 0.18,
      effectBounds: {
        min: new THREE.Vector3(-bodyRadiusBottom * 0.72, 0.12, -bodyRadiusBottom * 0.72),
        max: new THREE.Vector3(bodyRadiusBottom * 0.72, mouthY + 0.1, bodyRadiusBottom * 0.72),
      },
    },
    state,
    meta: {
      visualFamily: 'classic-showcase',
    },
  });

  apparatus.controllers.setGasOpacity = (nextOpacity = gasOpacity) => {
    if (!gasVolume) {
      return;
    }
    const clamped = Math.max(0, Math.min(1, nextOpacity));
    gasVolume.material.opacity = clamped;
    gasVolume.visible = clamped > 0.002;
    state.gasOpacity = clamped;
  };

  const { labelPlane } = attachFixedPlaneLabel({
    group,
    labelAnchor: anchors.labelAnchor,
    planeGeometry: new THREE.PlaneGeometry(Math.max(bodyRadiusBottom * 1.18, 0.82), Math.max(bodyHeight * 0.24, 0.46)),
    role: 'vessel-body-label',
  });
  attachLabelController(apparatus, labelPlane, { defaultAccent: '#cfe56d' });
  if (gasVolume) {
    apparatus.controllers.setGasOpacity(gasOpacity);
  }
  return apparatus;
}

function createClassicMoistPaperApparatus({
  parent,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  length = 0.72,
  width = 0.18,
  thickness = 0.012,
  contactRatio = 0.48,
  materials = {},
  color = 0xf26b28,
  wetColor = 0xe58b52,
  wireLength = 0,
  wireRadius = 0.01,
  wireColor = 0x8d96a2,
  stopperRadius = 0,
  stopperHeight = 0.14,
  stopperColor = 0xd0c5a0,
  name = 'classic-moist-paper',
} = {}) {
  const group = new THREE.Group();
  group.name = name;
  applyTransform(group, position, rotation);
  addToParent(parent, group);

  const stripMaterial = cloneMaterial(
    materials.strip,
    new THREE.MeshStandardMaterial({ color, roughness: 0.9, metalness: 0 }),
  );
  const wetMaterial = cloneMaterial(
    materials.contact,
    new THREE.MeshStandardMaterial({ color: wetColor, roughness: 0.72, metalness: 0, transparent: true, opacity: 0.88 }),
  );

  const strip = new THREE.Mesh(
    new THREE.BoxGeometry(width, length, thickness),
    stripMaterial,
  );
  strip.castShadow = true;
  strip.receiveShadow = true;
  group.add(strip);

  const contactPatch = new THREE.Mesh(
    new THREE.BoxGeometry(width * 0.94, length * contactRatio, thickness * 1.12),
    wetMaterial,
  );
  contactPatch.position.y = -(length * 0.5) + (length * contactRatio * 0.5);
  contactPatch.position.z = thickness * 0.06;
  group.add(contactPatch);

  const stripTopY = length * 0.5;
  let wire = null;
  if (wireLength > 0) {
    wire = new THREE.Mesh(
      new THREE.CylinderGeometry(wireRadius, wireRadius, wireLength, 16),
      cloneMaterial(
        materials.wire,
        new THREE.MeshStandardMaterial({ color: wireColor, roughness: 0.34, metalness: 0.74 }),
      ),
    );
    wire.position.y = stripTopY + wireLength * 0.5;
    wire.castShadow = true;
    group.add(wire);
  }

  let stopper = null;
  if (stopperRadius > 0) {
    stopper = new THREE.Mesh(
      new THREE.CylinderGeometry(stopperRadius * 0.94, stopperRadius, stopperHeight, 20),
      cloneMaterial(
        materials.stopper,
        new THREE.MeshStandardMaterial({ color: stopperColor, roughness: 0.82, metalness: 0.04 }),
      ),
    );
    stopper.position.y = stripTopY + Math.max(0, wireLength) + stopperHeight * 0.5;
    stopper.castShadow = true;
    stopper.receiveShadow = true;
    group.add(stopper);
  }

  const tipY = -length * 0.5 + thickness;
  const sampleZoneY = -(length * 0.5) + length * contactRatio * 0.46;
  const stopperSeatY = stopper
    ? stopper.position.y - stopperHeight * 0.5
    : stripTopY + Math.max(0, wireLength);
  const probeGripY = stopper
    ? stopper.position.y + stopperHeight * 0.18
    : stripTopY + Math.max(0, wireLength) + Math.max(length * 0.08, 0.05);

  const anchors = {
    labelAnchor: makeAnchor(group, 0, length * 0.64, 0, `${name}:labelAnchor`),
    gripAnchor: makeAnchor(group, 0, length * 0.24, 0, `${name}:gripAnchor`),
    probeGrip: makeAnchor(group, 0, probeGripY, 0, `${name}:probeGrip`),
    stopperSeat: makeAnchor(group, 0, stopperSeatY, 0, `${name}:stopperSeat`),
    tipAnchor: makeAnchor(group, 0, tipY, 0, `${name}:tipAnchor`),
    sampleZone: makeAnchor(group, 0, sampleZoneY, 0, `${name}:sampleZone`),
  };

  const state = {
    wetness: 0,
    indicatorColor: new THREE.Color(color),
    contactPose: 0,
  };

  const basePosition = new THREE.Vector3(...position);
  const baseRotation = new THREE.Euler(...rotation);
  const travel = new THREE.Vector3(0, -length * 0.18, 0);
  const tilt = [0.18, 0, -0.22];

  const apparatus = composeApparatus({
    kind: 'classic-moist-paper',
    family: 'classic-showcase-tool',
    group,
    meshes: { strip, contactPatch, wire, stopper },
    anchors,
    constraints: {
      tipInset: length * 0.04,
      contactLength: length * contactRatio,
      contactWidth: width * 0.94,
      effectBounds: {
        min: new THREE.Vector3(-width * 0.62, -length * 0.52, -thickness * 1.5),
        max: new THREE.Vector3(
          Math.max(width * 0.62, stopperRadius * 1.08),
          Math.max(length * 0.52, stopperSeatY + stopperHeight * 1.05),
          Math.max(thickness * 1.5, stopperRadius * 1.08),
        ),
      },
    },
    state,
    meta: {
      basePosition,
      baseRotation,
      visualFamily: 'classic-showcase',
    },
  });

  apparatus.controllers.setIndicatorColor = (nextColor) => {
    const value = new THREE.Color(nextColor);
    state.indicatorColor.copy(value);
    strip.material.color.copy(value);
    contactPatch.material.color.copy(value);
  };
  apparatus.controllers.setWetness = (value) => {
    const wetness = clamp(value, 0, 1);
    state.wetness = wetness;
    contactPatch.material.opacity = 0.2 + wetness * 0.68;
    contactPatch.visible = wetness > 0.01;
  };
  apparatus.controllers.setContactPose = (progress) => {
    const value = clamp(progress, 0, 1);
    state.contactPose = value;
    group.position.copy(basePosition).addScaledVector(travel, value);
    group.rotation.set(
      baseRotation.x + tilt[0] * value,
      baseRotation.y + tilt[1] * value,
      baseRotation.z + tilt[2] * value,
    );
  };

  const { labelPlane } = attachFixedPlaneLabel({
    group,
    labelAnchor: anchors.labelAnchor,
    planeGeometry: new THREE.PlaneGeometry(0.96, 0.36),
    role: 'floating-badge',
  });
  attachLabelController(apparatus, labelPlane, { defaultAccent: '#f0a055' });
  apparatus.controllers.setIndicatorColor(color);
  apparatus.controllers.setWetness(0);
  return apparatus;
}

const ChemApparatusLib = {
  THREE,
  APPARATUS_THREE_CDN,
  clamp,
  makeAnchor,
  getAnchorWorld,
  getApparatusId,
  composeApparatus,
  computeCylinderLiquidMetrics,
  setCylinderLiquidLevel,
  createCylinderLiquidController,
  clearWater,
  diluteAcid,
  createClassicTestTubeApparatus,
  createClassicSolidReagentJarApparatus,
  createClassicCopperPieceApparatus,
  createClassicReagentBottleApparatus,
  createZincGranulesApparatus,
  createClassicErlenmeyerApparatus,
  createClassicMoistPaperApparatus,
};

globalThis.ChemApparatusLib = ChemApparatusLib;

